function renderUsers(users) {
  const tbody = document.getElementById('usersTableBody');
  tbody.innerHTML = '';

  users.forEach(user => {
    const tr = document.createElement('tr');
    const adminBadge = user.is_admin
      ? '<span class="badge badge-admin">Admin</span>'
      : '<span class="badge badge-user">User</span>';
    const adminButton = user.is_admin
      ? `<button class="btn-remove-admin" onclick="toggleAdmin(${user.id}, false)">Remove Admin</button>`
      : `<button class="btn-admin" onclick="toggleAdmin(${user.id}, true)">Make Admin</button>`;
    tr.innerHTML = `
      <td class="checkbox-col"><input type="checkbox" class="user-checkbox" value="${user.id}" onchange="updateDeleteButton()"></td>
      <td>${user.id}</td>
      <td>${user.email}</td>
      <td class="username-cell" title="${user.username || ''}">${user.username || '<em>none</em>'}</td>
      <td>${user.external_id || '<em>none</em>'}</td>
      <td class="api-key-cell" title="${user.api_key || ''}">${user.api_key || '<em>none</em>'}</td>
      <td><span class="badge ${user.is_active ? 'badge-active' : 'badge-inactive'}">${user.is_active ? 'Active' : 'Inactive'}</span></td>
      <td>${adminBadge}</td>
      <td><span class="badge ${user.email_verified ? 'badge-verified' : 'badge-unverified'}">${user.email_verified ? 'Verified' : 'Unverified'}</span></td>
      <td>${formatDate(user.created_at)}</td>
      <td>${user.last_login_at ? formatDate(user.last_login_at) : 'Never'}</td>
      <td class="actions-cell">
        ${adminButton}
        <button class="btn-edit" onclick="editUser(${user.id})">Edit</button>
        <button class="btn-warning" onclick="resetUserPassword(${user.id})">Reset Password</button>
        <button class="delete-btn" onclick="deleteUser(${user.id})">Delete</button>
      </td>
    `;
    tbody.appendChild(tr);
  });

  // Reset select all checkbox
  document.getElementById('selectAll').checked = false;
  updateDeleteButton();
}

