function editUser(userId) {
  const user = allUsers.find(u => u.id === userId);
  if (!user) return;

  document.getElementById('modalTitle').textContent = 'Edit User';
  document.getElementById('userId').value = user.id;
  document.getElementById('userEmail').value = user.email;
  document.getElementById('userUsername').value = user.username || '';
  document.getElementById('userPassword').value = '';
  document.getElementById('userPassword').required = false;
  document.getElementById('userStatus').value = user.is_active.toString();
  document.getElementById('userIsAdmin').value = (user.is_admin || false).toString();
  document.getElementById('userEmailVerified').value = user.email_verified.toString();
  document.getElementById('userExternalId').value = user.external_id || '';
  document.getElementById('modalMessage').style.display = 'none';
  document.getElementById('userModal').style.display = 'block';
}

function closeUserModal() {
  document.getElementById('userModal').style.display = 'none';
}

async function saveUser(event) {
  event.preventDefault();

  const userId = document.getElementById('userId').value;
  const userData = {
    email: document.getElementById('userEmail').value,
    username: document.getElementById('userUsername').value || null,
    password: document.getElementById('userPassword').value || null,
    is_active: document.getElementById('userStatus').value === 'true',
    is_admin: document.getElementById('userIsAdmin').value === 'true',
    email_verified: document.getElementById('userEmailVerified').value === 'true',
    external_id: document.getElementById('userExternalId').value || null
  };

  try {
    let response;
    if (userId) {
      // Edit user
      if (!userData.password) delete userData.password;
      response = await fetch(addPasswordParam(`/api/admin/users/${userId}`), {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(userData)
      });
    } else {
      // Add user
      if (!userData.password) {
        alert('Password is required for new users');
        return;
      }
      response = await fetch(addPasswordParam(`/api/admin/users/create`), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(userData)
      });
    }

    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'Failed to save user');
    }

    closeUserModal();
    loadUsers();
  } catch (error) {
    const msgEl = document.getElementById('modalMessage');
    msgEl.textContent = error.message;
    msgEl.className = 'message error';
    msgEl.style.display = 'block';
  }
}

async function resetUserPassword(userId) {
  if (!confirm('Send password reset email to this user?')) return;

  try {
    const response = await fetch(addPasswordParam(`/api/admin/users/${userId}/reset-password`), {
      method: 'POST'
    });

    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'Failed to reset password');
    }

    alert('Password reset email sent successfully');
  } catch (error) {
    alert('Error: ' + error.message);

