	}

	// Add pagination controls inline in the summary
	html += `<div style="margin-top: 10px;">`

	// Helper function to build query parameters
	buildURL := func(pageNum int) string {
		params := []string{}
		if password != "" {
			params = append(params, "password="+password)
		}
