				<th class="sortable" onclick="sortTable(3)" data-type="text">Type</th>
				<th class="sortable" onclick="sortTable(4)" data-type="text">Track ID</th>
				<th class="sortable" onclick="sortTable(5)" data-type="text">Detector</th>
