// apiTracksBoundsHandler, qrPngHandler in pkg/httpapi

// generateTileCacheKey creates a unique key for caching clustered markers based on request parameters
// The key includes zoom level, bounding box, track ID, speed filters, and date filters
func generateTileCacheKey(zoom int, minLat, minLon, maxLat, maxLon float64, trackID, trackIDsParam string, speedRanges []database.SpeedRange, dateFrom, dateTo int64) string {
	// Create a string representation of speed ranges
	speedStr := ""
	for _, sr := range speedRanges {
		speedStr += fmt.Sprintf("%.2f-%.2f,", sr.Min, sr.Max)
	}

	// Format the key with all relevant parameters
	return fmt.Sprintf("tile:%d:%.6f:%.6f:%.6f:%.6f:%s:%s:%s:%d:%d",
		zoom, minLat, minLon, maxLat, maxLon, trackID, trackIDsParam, speedStr, dateFrom, dateTo)
}

// getMarkersHandler — берёт маркеры в заданном окне и фильтрах
// +НОВОЕ: dateFrom/dateTo (UNIX-seconds) диапазон времени.
func getMarkersHandler(w http.ResponseWriter, r *http.Request) {
	// Use the request context so map tiles cancel promptly when the browser closes,
	// freeing the serialized DuckDB lane for ongoing imports.
	ctx := r.Context()

	q := r.URL.Query()
	zoom, _ := strconv.Atoi(q.Get("zoom"))
	minLat, _ := strconv.ParseFloat(q.Get("minLat"), 64)
	minLon, _ := strconv.ParseFloat(q.Get("minLon"), 64)
	maxLat, _ := strconv.ParseFloat(q.Get("maxLat"), 64)
	maxLon, _ := strconv.ParseFloat(q.Get("maxLon"), 64)
	trackID := q.Get("trackID")
	trackIDsParam := q.Get("trackIDs") // Multiple tracks

	// ----- ✈️🚗🚶 фильтр скорости  ---------------------------------
	var sr []database.SpeedRange
	if s := q.Get("speeds"); s != "" {
		for _, tag := range strings.Split(s, ",") {
			if r, ok := speedCatalog[tag]; ok {
				sr = append(sr, database.SpeedRange(r))
			}
		}
	}
	if len(sr) == 0 && q.Get("speeds") != "" { // все выключены
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte("[]"))
		return
	}

	// ----- ⏱️  фильтр времени  ------------------------------------
	var (
		dateFrom int64
		dateTo   int64
	)
	if s := q.Get("dateFrom"); s != "" {
		dateFrom, _ = strconv.ParseInt(s, 10, 64)
	}
	if s := q.Get("dateTo"); s != "" {
		dateTo, _ = strconv.ParseInt(s, 10, 64)
	}

	// ----- запрос к БД  ------------------------------------------
	// ON-THE-FLY CLUSTERING: Always query zoom=0 (raw markers), then cluster client-side
	// This allows storing only raw markers in DB (~10x storage savings)
	const rawZoom = 0
	var (
		markers []database.Marker
		err     error
	)
	if trackID != "" {
		markers, err = db.GetMarkersByTrackIDZoomBoundsSpeed(
			ctx,
			trackID, rawZoom, minLat, minLon, maxLat, maxLon,
			dateFrom, dateTo, sr, *dbType)
	} else if trackIDsParam != "" {
		// Handle multiple tracks
		trackIDs := strings.Split(trackIDsParam, ",")
		for _, tid := range trackIDs {
			tid = strings.TrimSpace(tid)
			if tid == "" {
				continue
			}
			trackMarkers, trackErr := db.GetMarkersByTrackIDZoomBoundsSpeed(
				ctx,
				tid, rawZoom, minLat, minLon, maxLat, maxLon,
				dateFrom, dateTo, sr, *dbType)
			if trackErr != nil {
				log.Printf("Error fetching markers for track %s: %v", tid, trackErr)
				continue
			}
			markers = append(markers, trackMarkers...)
		}
	} else {
		markers, err = db.GetMarkersByZoomBoundsSpeed(
			ctx,
			rawZoom, minLat, minLon, maxLat, maxLon,
			dateFrom, dateTo, sr, *dbType)
	}
	if err != nil {
		log.Printf("Error fetching markers: %v (zoom=%d, bounds=[%f,%f,%f,%f], dbType=%s)", err, rawZoom, minLat, minLon, maxLat, maxLon, *dbType)
		http.Error(w, "Error fetching markers", http.StatusInternalServerError)
		return
	}

	// Generate cache key based on request parameters
	cacheKey := generateTileCacheKey(zoom, minLat, minLon, maxLat, maxLon, trackID, trackIDsParam, sr, dateFrom, dateTo)

	// Check if clustered markers are already in cache
	tileCacheMu.RLock()
	cachedMarkers, found := tileCache.Get(cacheKey)
	tileCacheMu.RUnlock()

	if found {
		// Use cached markers if available
		markers = cachedMarkers

		// Add realtime markers if enabled (these shouldn't be cached as they change frequently)
		if *safecastRealtimeEnabled {
			// We only touch realtime tables when the operator explicitly enables the feature.
			if rt, err := db.GetLatestRealtimeByBounds(ctx, minLat, minLon, maxLat, maxLon, *dbType); err == nil {
				for i := range rt {
					// Sanitise detector names on the fly so legacy rows without
					// the new resolver still produce friendly popups.
					rt[i].Tube = safecastrealtime.DetectorLabel(rt[i].Tube, rt[i].Transport, rt[i].DeviceName)
				}
				markers = append(markers, rt...)
			} else {
				log.Printf("realtime query: %v", err)
			}
		}
	} else {
		// Apply on-the-fly clustering based on requested zoom level (this is the expensive operation)
		markers = clusterMarkersForZoom(markers, zoom)

		// Add to cache for future requests (but don't cache if there are too many markers to avoid memory issues)
		if len(markers) < 10000 { // arbitrary limit to prevent cache bloat
			tileCacheMu.Lock()
			tileCache.Add(cacheKey, markers)
			tileCacheMu.Unlock()
		}

		// Add realtime markers if enabled
		if *safecastRealtimeEnabled {
			// We only touch realtime tables when the operator explicitly enables the feature.
			if rt, err := db.GetLatestRealtimeByBounds(ctx, minLat, minLon, maxLat, maxLon, *dbType); err == nil {
				for i := range rt {
					// Sanitise detector names on the fly so legacy rows without
					// the new resolver still produce friendly popups.
					rt[i].Tube = safecastrealtime.DetectorLabel(rt[i].Tube, rt[i].Transport, rt[i].DeviceName)
				}
				markers = append(markers, rt...)
			} else {
				log.Printf("realtime query: %v", err)
			}
		}
	}

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(markers)
}

// ========
// Streaming markers via SSE
// ========

// aggregateMarkers chooses the most radioactive marker per grid cell while merging the
// static query feed with an optional live stream. Keeping the grid map inside the goroutine
// lets us reuse previous emissions and drop later duplicates without mutexes.
// Markers with spectral data are prioritized over those without.
func aggregateMarkers(ctx context.Context, base <-chan database.Marker, updates <-chan database.Marker, zoom int) <-chan database.Marker {
	out := make(chan database.Marker)
	go func() {
		defer close(out)
		cells := make(map[string]database.Marker)
		scale := math.Pow(2, float64(zoom))
		baseCh := base
		updateCh := updates

		emit := func(m database.Marker) {
			key := fmt.Sprintf("%d:%d", int(m.Lat*scale), int(m.Lon*scale))
			prev, exists := cells[key]

			// Decide if this marker should replace the previous one:
			// 1. No previous marker exists, OR
			// 2. New marker has spectrum and previous doesn't, OR
			// 3. Both have same spectrum status and new has higher dose rate
			shouldReplace := !exists ||
				(m.HasSpectrum && !prev.HasSpectrum) ||
				(m.HasSpectrum == prev.HasSpectrum && m.DoseRate > prev.DoseRate)

			if shouldReplace {
				cells[key] = m
				select {
				case out <- m:
				case <-ctx.Done():
				}
			}
		}

		for {
			select {
			case <-ctx.Done():
				return
			case m, ok := <-baseCh:
				if !ok {
					baseCh = nil
					if baseCh == nil && updateCh == nil {
						return
					}
					continue
				}
				emit(m)
			case m, ok := <-updateCh:
				if !ok {
					updateCh = nil
					if baseCh == nil && updateCh == nil {
						return
					}
					continue
				}
				emit(m)
			}
		}
	}()
	return out
}

// calculateSampleRate determines what percentage of markers to send based on zoom level.
// Lower zoom = higher density = lower sample rate to reduce network traffic and client load.
func calculateSampleRate(zoom int, minLat, minLon, maxLat, maxLon float64) float64 {
	// Always send all markers for track view or high zoom levels
	if zoom >= 8 {
		return 1.0
	}

	// Calculate viewport area (approximate)
	latSpan := maxLat - minLat
	lonSpan := maxLon - minLon
	area := latSpan * lonSpan

	// For very large areas at low zoom, more aggressive sampling is needed
	// At zoom 7, Europe view is ~9.5 lat × 19.5 lon ≈ 185 sq degrees
	_ = area // Used for future density calculations

	// Sample rate based on zoom level to achieve target performance
	// More aggressive sampling for smoother performance
	// Zoom 7: ~15% (1 in 7) - increased for better visibility
	// Zoom 6: ~20% (1 in 5)  - increased for better visibility
	// Zoom 5 and below: ~2% (1 in 50) - down from 10%
	switch zoom {
	case 7:
		return 0.15 // Send 15% of markers (skip 85%)
	case 6:
		return 0.20 // Send 20% of markers (skip 80%)
	default: // zoom <= 5
		return 0.02 // Send 2% of markers (skip 98%)
	}
}

// sampleMarkerChannel applies statistical sampling to a marker stream.
// Returns a new channel that emits only a fraction of markers based on sampleRate.
func sampleMarkerChannel(ctx context.Context, in <-chan database.Marker, sampleRate float64) <-chan database.Marker {
	out := make(chan database.Marker, 100)

	go func() {
		defer close(out)
		counter := 0

		for m := range in {
			// Deterministic sampling based on marker ID for consistency
			// Use modulo to ensure even distribution
			counter++

			// Convert sample rate to skip pattern
			// e.g., 0.25 = keep every 4th marker
			skipInterval := int(1.0 / sampleRate)
			if skipInterval < 1 {
				skipInterval = 1
			}

			// Keep marker if counter is divisible by skip interval
			if counter%skipInterval == 0 {
				select {
				case out <- m:
				case <-ctx.Done():
					return
				}
			}
		}
	}()

	return out
}

// streamMultipleTracks merges marker streams from multiple tracks into a single channel
func streamMultipleTracks(ctx context.Context, trackIDs []string, zoom int, minLat, minLon, maxLat, maxLon float64, dbType string) (<-chan database.Marker, <-chan error) {
	out := make(chan database.Marker)
	errOut := make(chan error, len(trackIDs))

	var wg sync.WaitGroup

	for _, trackID := range trackIDs {
		trackID = strings.TrimSpace(trackID)
		if trackID == "" {
			continue
		}

		wg.Add(1)
		go func(tid string) {
			defer wg.Done()

			markerCh, errCh := db.StreamMarkersByTrackIDZoomAndBounds(ctx, tid, zoom, minLat, minLon, maxLat, maxLon, dbType)

			for {
				select {
				case <-ctx.Done():
					return
				case err, ok := <-errCh:
					if !ok {
						return
					}
					if err != nil {
						select {
						case errOut <- err:
						case <-ctx.Done():
							return
						}
					}
				case marker, ok := <-markerCh:
					if !ok {
						return
					}
					select {
					case out <- marker:
					case <-ctx.Done():
						return
					}
				}
			}
		}(trackID)
	}

	// Close output channel when all tracks are done
	go func() {
		wg.Wait()
		close(out)
		close(errOut)
	}()

	return out, errOut
}

// streamMarkersHandler streams markers via Server-Sent Events or MessagePack binary.
// Markers are emitted as soon as they are read and aggregated.
// Use ?format=msgpack for binary encoding (~60% smaller, faster parsing).
func streamMarkersHandler(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	zoom, _ := strconv.Atoi(q.Get("zoom"))
	minLat, _ := strconv.ParseFloat(q.Get("minLat"), 64)
	minLon, _ := strconv.ParseFloat(q.Get("minLon"), 64)
	maxLat, _ := strconv.ParseFloat(q.Get("maxLat"), 64)
	maxLon, _ := strconv.ParseFloat(q.Get("maxLon"), 64)
	trackID := q.Get("trackID")
	trackIDsParam := q.Get("trackIDs")
	showFilter := q.Get("show") // "rt" = realtime only, skip historical data

	// Check if client requests MessagePack binary format
	useMsgpack := q.Get("format") == "msgpack" ||
		strings.Contains(r.Header.Get("Accept"), "application/msgpack")

	// PERFORMANCE: Calculate density-based sampling rate for low zoom levels
	// This reduces network traffic and client-side processing for dense views
	sampleRate := calculateSampleRate(zoom, minLat, minLon, maxLat, maxLon)
	if sampleRate < 1.0 {
		log.Printf("density reduction: zoom=%d rate=%.2f (sending ~%.0f%% of markers)",
			zoom, sampleRate, sampleRate*100)
	}

	// ON-THE-FLY CLUSTERING: Always query zoom=0 (raw markers)
	// The aggregateMarkers function will cluster based on requested zoom
	const rawZoom = 0

	// Choose streaming source: either entire map, a single track, or multiple tracks
	// When showFilter=="rt", skip historical data entirely for faster RT-only views.
	ctx := r.Context()
	var (
		baseSrc <-chan database.Marker
		errCh   <-chan error
	)
	rtOnly := showFilter == "rt"
	if rtOnly && trackID == "" && trackIDsParam == "" {
		// In RT-only mode for global view, still load historical markers
		// They will be filtered client-side, but spectrum markers should be available
		baseSrc, errCh = db.StreamMarkersByZoomAndBounds(ctx, rawZoom, minLat, minLon, maxLat, maxLon, *dbType)
	} else if trackID != "" {
		baseSrc, errCh = db.StreamMarkersByTrackIDZoomAndBounds(ctx, trackID, rawZoom, minLat, minLon, maxLat, maxLon, *dbType)
	} else if trackIDsParam != "" {
		// Handle multiple tracks by merging their streams
		trackIDs := strings.Split(trackIDsParam, ",")
		baseSrc, errCh = streamMultipleTracks(ctx, trackIDs, rawZoom, minLat, minLon, maxLat, maxLon, *dbType)
	} else {
		baseSrc, errCh = db.StreamMarkersByZoomAndBounds(ctx, rawZoom, minLat, minLon, maxLat, maxLon, *dbType)
	}

	// Fetch current realtime points once so the map reflects network devices.
	// We only touch the realtime table when the dedicated flag enables it so
	// operators control the feature explicitly.
	var rtMarks []database.Marker
	if *safecastRealtimeEnabled {
		var err error
		rtMarks, err = db.GetLatestRealtimeByBounds(ctx, minLat, minLon, maxLat, maxLon, *dbType)
		if err != nil {
			log.Printf("realtime query: %v", err)
		}
		// Log bounds alongside count to help diagnose empty map tiles.
		log.Printf("realtime markers: %d lat[%f,%f] lon[%f,%f]", len(rtMarks), minLat, maxLat, minLon, maxLon)
	}

	// Apply density-based sampling if needed (zoom < 8)
	var sampledSrc <-chan database.Marker
	if sampleRate < 1.0 {
		sampledSrc = sampleMarkerChannel(ctx, baseSrc, sampleRate)
	} else {
		sampledSrc = baseSrc
	}

	agg := aggregateMarkers(ctx, sampledSrc, nil, zoom)

	// Set appropriate headers based on format
	if useMsgpack {
		w.Header().Set("Content-Type", "application/octet-stream")
		w.Header().Set("X-Content-Format", "msgpack")
	} else {
		w.Header().Set("Content-Type", "text/event-stream")
	}
	w.Header().Set("Cache-Control", "no-cache")
	flusher, ok := w.(http.Flusher)
	if !ok {
		http.Error(w, "Streaming unsupported", http.StatusInternalServerError)
		return
	}

	// Helper to write a msgpack frame: 4-byte length prefix + data
	writeMsgpackFrame := func(data []byte) {
		lenBuf := make([]byte, 4)
		binary.BigEndian.PutUint32(lenBuf, uint32(len(data)))
		w.Write(lenBuf)
		w.Write(data)
	}

	// Emit realtime markers first when enabled.
	for _, m := range rtMarks {
		if useMsgpack {
			b, _ := msgpack.Marshal(m)
			writeMsgpackFrame(b)
		} else {
			b, _ := json.Marshal(m)
			fmt.Fprintf(w, "data: %s\n\n", b)
		}
	}
	flusher.Flush()

	for {
		select {
		case <-ctx.Done():
			return
		case err, ok := <-errCh:
			if !ok {
				errCh = nil
				continue
			}
			if err != nil {
				if useMsgpack {
					// Send zero-length frame as error indicator
					w.Write([]byte{0, 0, 0, 0})
				} else {
					fmt.Fprintf(w, "event: done\ndata: %v\n\n", err)
				}
				flusher.Flush()
				return
			}
			errCh = nil
		case m, ok := <-agg:
			if !ok {
				if useMsgpack {
					// Send zero-length frame as end marker
					w.Write([]byte{0, 0, 0, 0})
				} else {
					fmt.Fprint(w, "event: done\ndata: end\n\n")
				}
				flusher.Flush()
				return
			}
			if useMsgpack {
				b, _ := msgpack.Marshal(m)
				writeMsgpackFrame(b)
			} else {
				b, _ := json.Marshal(m)
				fmt.Fprintf(w, "data: %s\n\n", b)
			}
			flusher.Flush()
		}
	}
}

// realtimePoint holds a single measurement for realtime history charts.
// Keeping the struct tiny helps when we duplicate slices for aggregation.
type realtimePoint struct {
	Timestamp int64   `json:"timestamp"`
	Value     float64 `json:"value"`
}

// rangeSummary describes the plotted window and aggregation bucket.
// Returning it to the frontend lets JavaScript render friendly titles.
type rangeSummary struct {
	Start         int64 `json:"start"`
	End           int64 `json:"end"`
	BucketSeconds int64 `json:"bucketSeconds"`
}

// historyAggregate bundles the processed realtime readings so the handler can
// serialise the JSON response without juggling several parallel slices.
type historyAggregate struct {
	Series      map[string][]realtimePoint
	ExtraSeries map[string]map[string][]realtimePoint
	Extra       map[string]float64
	Ranges      map[string]rangeSummary
	DeviceName  string
	Transport   string
	Tube        string
	Country     string
}

// realtimeMeasurementPayload moves measurements between goroutines without
// sharing mutable state and keeps channel signatures consistent across helpers.
type realtimeMeasurementPayload struct {
	timestamp int64
	radiation float64
	extras    map[string]float64
	name      string
	transport string
	tube      string
	country   string
}

// decodeRealtimeExtras converts the optional JSON blob with temperature or
// humidity hints into a float map.  Invalid payloads are ignored so noisy
// devices do not break chart rendering.
func decodeRealtimeExtras(raw string) map[string]float64 {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return nil
	}
	var parsed map[string]float64
	if err := json.Unmarshal([]byte(trimmed), &parsed); err != nil {
		log.Printf("decode realtime extras: %v", err)
		return nil
	}
	clean := make(map[string]float64, len(parsed))
	for key, value := range parsed {
		if math.IsNaN(value) || math.IsInf(value, 0) {
			continue
		}
		clean[key] = value
	}
	if len(clean) == 0 {
		return nil
	}
	return clean
}

// copyFloatMap duplicates a float map so later mutations do not affect cached
// responses.  We prefer copying over shared state to follow Go's advice of
// communicating values explicitly.
func copyFloatMap(src map[string]float64) map[string]float64 {
	if len(src) == 0 {
		return nil
	}
	dst := make(map[string]float64, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

// cloneRealtimePoints allocates a fresh slice so callers can trim or
// resample without affecting other views.
func cloneRealtimePoints(points []realtimePoint) []realtimePoint {
	if len(points) == 0 {
		return nil
	}
	out := make([]realtimePoint, len(points))
	copy(out, points)
	return out
}

// filterPointsSince keeps only values with timestamps at or after the cutoff.
// The helper assumes the input slice is sorted by timestamp.
func filterPointsSince(points []realtimePoint, cutoff int64) []realtimePoint {
	if cutoff <= 0 || len(points) == 0 {
		return cloneRealtimePoints(points)
	}
	idx := sort.Search(len(points), func(i int) bool {
		return points[i].Timestamp >= cutoff
	})
	if idx >= len(points) {
		return nil
	}
	return cloneRealtimePoints(points[idx:])
}

// resampleRealtimePoints collapses samples into evenly sized buckets using the
// average value per bucket.  Returning a new slice keeps the caller's data
// immutable and mirrors the "don't mutate shared structures" guidance.
func resampleRealtimePoints(points []realtimePoint, bucket int64) []realtimePoint {
	if bucket <= 0 || len(points) == 0 {
		return cloneRealtimePoints(points)
	}
	out := make([]realtimePoint, 0, len(points))
	currentBucket := (points[0].Timestamp / bucket) * bucket
	var sum float64
	var count int
	for _, p := range points {
		bucketID := (p.Timestamp / bucket) * bucket
		if bucketID != currentBucket && count > 0 {
			out = append(out, realtimePoint{
				Timestamp: currentBucket + bucket/2,
				Value:     sum / float64(count),
			})
			currentBucket = bucketID
			sum = 0
			count = 0
		}
		sum += p.Value
		count++
	}
	if count > 0 {
		out = append(out, realtimePoint{
			Timestamp: currentBucket + bucket/2,
			Value:     sum / float64(count),
		})
	}
	return out
}

// lastNRealtimePoints keeps only the newest buckets so short charts honour fixed
// divisions without redrawing hundreds of samples. Copying avoids sharing slices.
func lastNRealtimePoints(points []realtimePoint, keep int) []realtimePoint {
	if keep <= 0 || len(points) == 0 {
		return nil
	}
	if len(points) <= keep {
		return points
	}
	out := make([]realtimePoint, keep)
	copy(out, points[len(points)-keep:])
	return out
}

// alignToCeil snaps timestamps up to the next step boundary so chart grids show
// whole buckets even when the latest measurement arrives mid-interval.
func alignToCeil(t time.Time, step time.Duration) time.Time {
	if step <= 0 {
		return t.UTC()
	}
	tt := t.UTC()
	truncated := tt.Truncate(step)
	if tt.Equal(truncated) {
		return tt
	}
	return truncated.Add(step)
}

// alignMonthCeil advances to the first day of the next month so the long-term
// chart can display complete calendar months without partial buckets.
func alignMonthCeil(t time.Time) time.Time {
	tt := t.UTC()
	base := time.Date(tt.Year(), tt.Month(), 1, 0, 0, 0, 0, time.UTC)
	return base.AddDate(0, 1, 0)
}

// aggregateMonthly groups samples by calendar month using the average value per
// month. This keeps the "months" chart faithful to calendar boundaries.
func aggregateMonthly(points []realtimePoint, start time.Time, months int) []realtimePoint {
	if months <= 0 || len(points) == 0 {
		return nil
	}
	startUTC := time.Date(start.UTC().Year(), start.UTC().Month(), 1, 0, 0, 0, 0, time.UTC)
	filtered := filterPointsSince(points, startUTC.Unix())
	if len(filtered) == 0 {
		return nil
	}
	out := make([]realtimePoint, 0, months)
	idx := 0
	for i := 0; i < months; i++ {
		monthStart := startUTC.AddDate(0, i, 0)
		monthEnd := monthStart.AddDate(0, 1, 0)
		startUnix := monthStart.Unix()
		endUnix := monthEnd.Unix()
		for idx < len(filtered) && filtered[idx].Timestamp < startUnix {
			idx++
		}
		if idx >= len(filtered) {
			break
		}
		sum := 0.0
		count := 0
		j := idx
		for j < len(filtered) {
			ts := filtered[j].Timestamp
			if ts >= endUnix {
				break
			}
			sum += filtered[j].Value
			count++
			j++
		}
		if count > 0 {
			mid := startUnix + (endUnix-startUnix)/2
			out = append(out, realtimePoint{Timestamp: mid, Value: sum / float64(count)})
			idx = j
		}
	}
	return out
}

// realtimeBucketSteps enumerates pleasant aggregation steps from minutes to
// months.  The list keeps resampling predictable and friendly on charts.
var realtimeBucketSteps = []int64{
	60,
	120,
	300,
	600,
	900,
	1800,
	3600,
	7200,
	14400,
	28800,
	43200,
	86400,
	172800,
	604800,
	1209600,
	2592000,
	7776000,
}

// pickNiceBucket chooses the smallest bucket from realtimeBucketSteps that is
// greater or equal to the requested minimum.  Falling back to doubling keeps
// the function total when the data spans many years.
func pickNiceBucket(minStep int64) int64 {
	if minStep <= 1 {
		return 1
	}
	for _, step := range realtimeBucketSteps {
		if step >= minStep {
			return step
		}
	}
	return realtimeBucketSteps[len(realtimeBucketSteps)-1]
}

// nextBucket returns the next larger bucket after the provided step.
func nextBucket(step int64) int64 {
	for _, candidate := range realtimeBucketSteps {
		if candidate > step {
			return candidate
		}
	}
	if step <= 0 {
		return 1
	}
	return step * 2
}

// prepareRealtimeSeries optionally resamples a slice so the frontend receives
// at most "limit" points.  When defaultBucket is positive we always aggregate
// using that duration; otherwise the function derives a pleasant step.
func prepareRealtimeSeries(points []realtimePoint, limit int, defaultBucket int64) ([]realtimePoint, int64) {
	if len(points) == 0 {
		return nil, 0
	}
	if defaultBucket > 0 {
		bucket := defaultBucket
		resampled := resampleRealtimePoints(points, bucket)
		for len(resampled) > limit {
			bucket = nextBucket(bucket)
			resampled = resampleRealtimePoints(points, bucket)
		}
		return resampled, bucket
	}
	if len(points) <= limit {
		return cloneRealtimePoints(points), 0
	}
	span := points[len(points)-1].Timestamp - points[0].Timestamp
	if span <= 0 {
		return cloneRealtimePoints(points), 0
	}
	approx := span / int64(limit)
	if approx <= 0 {
		approx = 1
	}
	bucket := pickNiceBucket(approx)
	resampled := resampleRealtimePoints(points, bucket)
	for len(resampled) > limit {
		bucket = nextBucket(bucket)
		resampled = resampleRealtimePoints(points, bucket)
	}
	return resampled, bucket
}

// summariseRealtimeHistory processes DB rows on a background goroutine and
// returns aggregated series for day, month, and all-time windows.
func summariseRealtimeHistory(rows []database.RealtimeMeasurement, now time.Time) historyAggregate {
	input := make(chan realtimeMeasurementPayload)
	go func() {
		defer close(input)
		for _, row := range rows {
			val, ok := safecastrealtime.FromRealtime(row.Value, row.Unit)
			if !ok {
				continue
			}
			payload := realtimeMeasurementPayload{
				timestamp: row.MeasuredAt,
				radiation: safecastrealtime.ToMicroRoentgen(val),
				extras:    decodeRealtimeExtras(row.Extra),
				name:      row.DeviceName,
				transport: row.Transport,
				tube:      row.Tube,
				country:   row.Country,
			}
			input <- payload
		}
	}()

	return collectRealtimeMeasurements(input, now, len(rows))
}

// collectRealtimeMeasurements consumes the measurement stream, keeps track of
// metadata, and prepares slices for each chart timeframe.
func collectRealtimeMeasurements(input <-chan realtimeMeasurementPayload, now time.Time, expected int) historyAggregate {
	agg := historyAggregate{
		Series: map[string][]realtimePoint{
			"day":   {},
			"month": {},
			"all":   {},
		},
		ExtraSeries: map[string]map[string][]realtimePoint{
			"day":   {},
			"month": {},
			"all":   {},
		},
		Ranges: make(map[string]rangeSummary, 3),
	}

	extrasAll := make(map[string][]realtimePoint)
	if expected <= 0 {
		expected = 1024
	}
	allPoints := make([]realtimePoint, 0, expected)
	var lastTs int64

	for payload := range input {
		point := realtimePoint{Timestamp: payload.timestamp, Value: payload.radiation}
		allPoints = append(allPoints, point)
		lastTs = payload.timestamp

		if agg.DeviceName == "" && payload.name != "" {
			agg.DeviceName = payload.name
		}
		if agg.Transport == "" && payload.transport != "" {
			agg.Transport = payload.transport
		}
		if agg.Country == "" && payload.country != "" {
			agg.Country = payload.country
		}
		if agg.Tube == "" {
			if label := safecastrealtime.DetectorLabel(payload.tube, payload.transport, payload.name); label != "" {
				agg.Tube = label
			}
		}

		if len(payload.extras) > 0 {
			agg.Extra = copyFloatMap(payload.extras)
			for key, value := range payload.extras {
				extrasAll[key] = append(extrasAll[key], realtimePoint{Timestamp: payload.timestamp, Value: value})
			}
		}
	}

	reference := now.UTC()
	if lastTs > 0 {
		lastSeen := time.Unix(lastTs, 0).UTC()
		if lastSeen.After(reference) {
			reference = lastSeen
		}
	}

	const (
		hourlySegments  = 24
		dailySegments   = 24
		monthlySegments = 24
	)
	const dayDuration = 24 * time.Hour

	dayEnd := alignToCeil(reference, time.Hour)
	dayStart := dayEnd.Add(-time.Duration(hourlySegments) * time.Hour)
	monthEnd := alignToCeil(reference, dayDuration)
	monthStart := monthEnd.Add(-time.Duration(dailySegments) * dayDuration)
	allEnd := alignMonthCeil(reference)
	allStart := allEnd.AddDate(0, -monthlySegments, 0)

	dayCutoff := dayStart.Unix()
	monthCutoff := monthStart.Unix()
	allCutoff := allStart.Unix()

	hourBucket := int64(time.Hour / time.Second)
	daySeries := lastNRealtimePoints(resampleRealtimePoints(filterPointsSince(allPoints, dayCutoff), hourBucket), hourlySegments)

	dayBucketSeconds := int64(dayDuration / time.Second)
	monthSeries := lastNRealtimePoints(resampleRealtimePoints(filterPointsSince(allPoints, monthCutoff), dayBucketSeconds), dailySegments)

	allSeries := aggregateMonthly(allPoints, allStart, monthlySegments)
	avgBucket := (allEnd.Sub(allStart) / time.Duration(monthlySegments)) / time.Second
	allBucketSeconds := int64(avgBucket)
	if allBucketSeconds <= 0 {
		allBucketSeconds = int64(30 * dayDuration / time.Second)
	}

	agg.Series["day"] = daySeries
	agg.Series["month"] = monthSeries
	agg.Series["all"] = allSeries
	agg.Ranges["day"] = rangeSummary{Start: dayCutoff, End: dayEnd.Unix(), BucketSeconds: hourBucket}
	agg.Ranges["month"] = rangeSummary{Start: monthCutoff, End: monthEnd.Unix(), BucketSeconds: dayBucketSeconds}
	agg.Ranges["all"] = rangeSummary{Start: allCutoff, End: allEnd.Unix(), BucketSeconds: allBucketSeconds}

	buildExtras := func(target string, cutoff int64, bucket int64) {
		if len(extrasAll) == 0 {
			return
		}
		series := make(map[string][]realtimePoint)
		for key, pts := range extrasAll {
			filtered := filterPointsSince(pts, cutoff)
			if len(filtered) == 0 {
				continue
			}
			if bucket > 0 {
				series[key] = resampleRealtimePoints(filtered, bucket)
			} else {
				series[key] = filtered
			}
		}
		if len(series) > 0 {
			agg.ExtraSeries[target] = series
		}
	}

	buildMonthlyExtras := func(target string, start time.Time, months int) {
		if len(extrasAll) == 0 {
			return
		}
		series := make(map[string][]realtimePoint)
		for key, pts := range extrasAll {
			aggregated := aggregateMonthly(pts, start, months)
			if len(aggregated) == 0 {
				continue
			}
			series[key] = aggregated
		}
		if len(series) > 0 {
			agg.ExtraSeries[target] = series
		}
	}

	buildExtras("day", dayCutoff, hourBucket)
	buildExtras("month", monthCutoff, dayBucketSeconds)
	buildMonthlyExtras("all", allStart, monthlySegments)

	if agg.Series["day"] == nil {
		agg.Series["day"] = []realtimePoint{}
	}
	if agg.Series["month"] == nil {
		agg.Series["month"] = []realtimePoint{}
	}
	if agg.Series["all"] == nil {
		agg.Series["all"] = []realtimePoint{}
	}

	return agg
}

// realtimeHistoryHandler returns one year of realtime measurements for a device.
// The handler keeps the response lightweight so the frontend can draw Grafana-style
// charts without shipping a dedicated dashboard backend.
func realtimeHistoryHandler(w http.ResponseWriter, r *http.Request) {
	if !*safecastRealtimeEnabled {
		http.NotFound(w, r)
		return
	}

	device := strings.TrimSpace(r.URL.Query().Get("device"))
	if device == "" {
		http.Error(w, "missing device", http.StatusBadRequest)
		return
	}
	if strings.HasPrefix(device, "live:") {
		device = strings.TrimPrefix(device, "live:")
	}

	now := time.Now()
	rows, err := db.GetRealtimeHistory(device, 0, *dbType)
	if err != nil {
		http.Error(w, "history error", http.StatusInternalServerError)
		return
	}

	historyCh := make(chan historyAggregate, 1)
	go func() {
		historyCh <- summariseRealtimeHistory(rows, now)
	}()

	var agg historyAggregate
	select {
	case <-r.Context().Done():
		http.Error(w, "request cancelled", http.StatusRequestTimeout)
		return
	case agg = <-historyCh:
	}

	resp := struct {
		DeviceID    string                                `json:"deviceID"`
		DeviceName  string                                `json:"deviceName,omitempty"`
		Transport   string                                `json:"transport,omitempty"`
		Tube        string                                `json:"tube,omitempty"`
		Country     string                                `json:"country,omitempty"`
		Series      map[string][]realtimePoint            `json:"series"`
		Extra       map[string]float64                    `json:"extra,omitempty"`
		ExtraSeries map[string]map[string][]realtimePoint `json:"extraSeries,omitempty"`
		Ranges      map[string]rangeSummary               `json:"ranges,omitempty"`
	}{
		DeviceID:    device,
		DeviceName:  agg.DeviceName,
		Transport:   agg.Transport,
		Tube:        agg.Tube,
		Country:     agg.Country,
		Series:      agg.Series,
		Extra:       agg.Extra,
		ExtraSeries: agg.ExtraSeries,
		Ranges:      agg.Ranges,
	}

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(resp)
}

// Gzip compression for API responses is in pkg/httpapi (Server.gzipWrap).

// =====================
// MAIN
// =====================

// main parses flags, initialises the DB & routes, then either
// (a) serves plain HTTP on a custom port, or
// (b) if -domain is given, serves ACME-backed HTTPS on 443 plus
//     an ACME/redirect helper on 80.
//
// If any web-server returns an error it is only logged – the
// application continues running.  A final `select{}` keeps the
// main goroutine alive without resorting to mutexes.

// main: парсинг флагов, инициализация БД и запуск веб-серверов.
// Добавлен withServerHeader для всех запросов.
// =====================
// MAIN
// =====================
func main() {
	// 1. Флаги и версии
	flag.Parse()
	debugIPAllowlist = parseDebugAllowlist(*debugIPsFlag)
	loadTranslationsFromFile(content, "public_html/translations.json")
	selfupgradeStartupDelay(log.Printf)

	archiveFrequency, freqErr := jsonarchive.ParseFrequency(*jsonArchiveFrequencyFlag)
	if freqErr != nil {
		log.Fatalf("json archive frequency: %v", freqErr)
	}
	archiveFileName := jsonarchive.FileName(*domain, archiveFrequency)

	if *version {
		fmt.Printf("safecast-new-map version %s\n", CompileVersion)
		return
	}

	// 2. Предупреждение о привилегиях (для :80 / :443)
	if *domain != "" && runtime.GOOS != "windows" && os.Geteuid() != 0 {
		log.Println("⚠  Binding to :80 / :443 requires super-user rights; run with sudo or as root.")
	}

	// 3. База данных
	driverName := strings.ToLower(strings.TrimSpace(*dbType))
	// Persist the normalized driver back into the flag so downstream helpers never
	// miss engine-specific branches because of incidental casing or whitespace.
	*dbType = driverName
	dbCfg := database.Config{
		DBType: driverName,
		DBPath: *dbPath,
		Port:   *port,
	}
	switch driverName {
	case "pgx":
		// Default PostgreSQL connection settings
		// Can be overridden via -db-conn flag or environment variables:
		// DB_HOST, DB_PORT, DB_USER, DB_PASS, DB_NAME, DB_SSLMODE
		dbCfg.DBHost = getEnvOrDefault("DB_HOST", "127.0.0.1")
		dbCfg.DBPort = getEnvIntOrDefault("DB_PORT", 5432)
		dbCfg.DBUser = getEnvOrDefault("DB_USER", "postgres")
		dbCfg.DBPass = getEnvOrDefault("DB_PASS", "")
		dbCfg.DBName = getEnvOrDefault("DB_NAME", "safecast")
		dbCfg.PGSSLMode = getEnvOrDefault("DB_SSLMODE", "prefer")
		// If -db-conn is provided, it overrides individual settings
		if err := applyDBConnection(driverName, *dbConn, &dbCfg); err != nil {
			log.Fatalf("DB config: %v", err)
		}
	case "clickhouse":
		dbCfg.DBHost = "127.0.0.1"
		dbCfg.DBPort = 9000
		dbCfg.DBName = "IsotopePathways"
		if err := applyDBConnection(driverName, *dbConn, &dbCfg); err != nil {
			log.Fatalf("DB config: %v", err)
		}
	default:
		if strings.TrimSpace(*dbConn) != "" {
			log.Fatalf("db-conn is only valid for pgx or clickhouse drivers (current: %s)", *dbType)
		}
	}
	var err error
	db, err = database.NewDatabase(dbCfg)
	if err != nil {
		log.Fatalf("DB init: %v", err)
	}
	defer func() {
		if closeErr := db.Close(); closeErr != nil {
			log.Printf("DB close: %v", closeErr)
		}
	}()
	if err = db.InitSchema(dbCfg); err != nil {
		log.Fatalf("DB schema: %v", err)
	}
	queueDuckDBMaintenanceAfterImport(driverName, db, log.Printf, "startup")

	// Seed translations into DB if empty, then reload from DB
	seedTranslationsDB(content, "public_html/translations.json")
	loadTranslationsFromDB()

	// Initialize authentication system if configured
	var authManager *auth.Manager
	var emailSender *email.Sender
	if *sessionSecret != "" && *smtpHost != "" {
		// Initialize email sender
		emailConfig := email.SMTPConfig{
			Host:     *smtpHost,
			Port:     *smtpPort,
			Username: *smtpUsername,
			Password: *smtpPassword,
			From:     *smtpFrom,
			FromName: *smtpFromName,
			UseTLS:   true,
		}
		emailSender = email.NewSender(emailConfig)

		// Initialize auth manager
		authManager = &auth.Manager{
			DB:                db.DB,
			DBDriver:          driverName,
			SessionCookieName: *sessionCookieName,
			AllowRegistration: *allowRegistration,
			EmailSender:       emailSender,
			BaseURL:           *baseURL,
		}

		log.Printf("Authentication system enabled")
	} else if *requireAuth {
		log.Fatalf("Authentication required but not properly configured. Set -session-secret and -smtp-host")
	}

	remoteURL := strings.TrimSpace(*importTGZURLFlag)
	localArchive := strings.TrimSpace(*importTGZFileFlag)
	if remoteURL != "" && localArchive != "" {
		log.Fatalf("choose only one import flag: -import-tgz-url or -import-tgz-file")
	}

	var importDone <-chan struct{}

	if localArchive != "" {
		fallback := GenerateSerialNumber()
		importDone = startBackgroundArchiveImport(context.Background(), fmt.Sprintf("local file %s", localArchive), func(ctx context.Context) error {
			return importArchiveFromFile(ctx, localArchive, fallback, db, driverName, log.Printf)
		}, log.Printf)
	}

	if remoteURL != "" {
		fallback := GenerateSerialNumber()
		importDone = startBackgroundArchiveImport(context.Background(), fmt.Sprintf("remote url %s", remoteURL), func(ctx context.Context) error {
			return importArchiveFromURL(ctx, remoteURL, fallback, db, driverName, log.Printf)
		}, log.Printf)
	}

	if *safecastRealtimeEnabled {
		// Launch realtime Safecast polling under the dedicated flag so the
		// feature stays opt-in.
		database.SetRealtimeConverter(safecastrealtime.FromRealtime)
		ctxRT, cancelRT := context.WithCancel(context.Background())
		defer cancelRT()
		safecastrealtime.Start(ctxRT, db, *dbType, log.Printf)
	}

	if *safecastFetcherEnabled {
		// Launch Safecast API fetcher to automatically import approved bGeigie logs
		ctxFetcher, cancelFetcher := context.WithCancel(context.Background())
		defer cancelFetcher()

		// Create importer function that bridges to existing import logic
		importerFunc := func(
			ctx context.Context,
			fileContent []byte,
			filename string,
			safecastImportID int64,
			sourceURL string,
			userID string,
			username string,
			db *database.Database,
			dbType string,
		) (trackID string, markerCount int, err error) {
			trackID = GenerateSerialNumber()

			// Create BytesFile from content
			bytesFile := safecastfetcher.NewBytesFile(fileContent, filename)

			// Parse and import the file
			_, finalTrackID, err := processBGeigieZenFile(bytesFile, trackID, db, dbType)
			if err != nil {
				return "", 0, fmt.Errorf("process bGeigie file: %w", err)
			}

			// Count markers for this track by querying the database
			countQuery := "SELECT COUNT(*) FROM markers WHERE trackID = ?"
			if dbType == "pgx" || dbType == "postgres" || dbType == "duckdb" {
				countQuery = "SELECT COUNT(*) FROM markers WHERE trackID = $1"
			}
			err = db.DB.QueryRowContext(ctx, countQuery, finalTrackID).Scan(&markerCount)
			if err != nil {
				// If count fails, log but don't fail the import
				log.Printf("[safecast-fetcher] warning: failed to count markers for track %s: %v", finalTrackID, err)
				markerCount = 0
			}

			// Get earliest marker date for this track to populate RecordingDate
			var recordingDate int64
			minDateQuery := "SELECT MIN(date) FROM markers WHERE trackID = ?"
			if dbType == "pgx" {
				minDateQuery = "SELECT MIN(date) FROM markers WHERE trackID = $1"
			}
			_ = db.DB.QueryRowContext(ctx, minDateQuery, finalTrackID).Scan(&recordingDate)

			// Get detector info from markers table
			var detector string
			detectorQuery := "SELECT COALESCE(detector, '') FROM markers WHERE trackID = ? AND detector != '' LIMIT 1"
			if dbType == "pgx" {
				detectorQuery = "SELECT COALESCE(detector, '') FROM markers WHERE trackID = $1 AND detector != '' LIMIT 1"
			}
			_ = db.DB.QueryRowContext(ctx, detectorQuery, finalTrackID).Scan(&detector)

			// Record the upload with source tracking
			upload := database.Upload{
				Filename:      filename,
				FileType:      ".log",
				TrackID:       finalTrackID,
				FileSize:      int64(len(fileContent)),
				UploadIP:      "safecast-api",
				CreatedAt:     time.Now().Unix(),
				RecordingDate: recordingDate, // Earliest marker date from log file
				Source:        safecastfetcher.SourceTypeSafecastAPI,
				SourceID:      fmt.Sprintf("%d", safecastImportID),
				SourceURL:     sourceURL,
				UserID:        userID,
				Username:      username,
				Detector:      detector,
			}

			if _, err := db.InsertUpload(ctx, upload); err != nil {
				return finalTrackID, markerCount, fmt.Errorf("record upload: %w", err)
			}

			return finalTrackID, markerCount, nil
		}

		// Set the default importer so GUI batch imports can use the same efficient code path
		safecastfetcher.DefaultImporter = importerFunc

		// Start the fetcher
		safecastfetcher.Start(ctxFetcher, safecastfetcher.Config{
			DB:           db,
			DBType:       *dbType,
			Interval:     *safecastFetcherInterval,
			BatchSize:    *safecastFetcherBatchSize,
			StartDate:    *safecastFetcherStartDate,
			Importer:     importerFunc,
			Logf:         log.Printf,
			BackfillMode: *safecastFetcherBackfill,
			NewestFirst:  *safecastFetcherNewestFirst,
		})

		log.Printf("safecast API fetcher enabled: interval=%s batch=%d start_date=%s backfill=%v newest_first=%v",
			*safecastFetcherInterval, *safecastFetcherBatchSize, *safecastFetcherStartDate, *safecastFetcherBackfill, *safecastFetcherNewestFirst)
	}

	// Build a JSON archive tgz with all known exported tracks only when
	// operators explicitly opt in via -json-archive-path. The cadence flag
	// keeps IO predictable while letting deployments choose how fresh the
	// bundle should be.
	var (
		archiveGen     *jsonarchive.Generator
		archiveCancel  context.CancelFunc
		archivePath    string
		archiveEnabled = strings.TrimSpace(*jsonArchivePathFlag) != ""
	)
	if archiveEnabled {
		ctxArchive, cancelArchive := context.WithCancel(context.Background())
		archiveCancel = cancelArchive
		archivePath = resolveArchivePath(*jsonArchivePathFlag, archiveFileName, log.Printf)
		if abs, err := filepath.Abs(archivePath); err == nil {
			archivePath = abs
		}
		log.Printf("json archive destination resolved: %s", archivePath)
		archiveGen = jsonarchive.Start(ctxArchive, db, *dbType, archivePath, archiveFileName, archiveFrequency.Interval(), log.Printf)
	} else {
		log.Printf("json archive disabled: set -json-archive-path to enable tarball generation")
	}
	if archiveCancel != nil {
		defer archiveCancel()
	}

	apiDocsArchiveEnabled = archiveEnabled
	route := archiveFrequency.RoutePath()
	if strings.TrimSpace(route) == "" {
		route = "/api/json/weekly.tgz"
	}
	apiDocsArchiveRoute = route
	apiDocsArchiveFrequency = archiveFrequency.HumanInterval()

	// Web server: handlers in pkg/httpapi.
	webConfig := httpapi.WebConfig{
		Domain:                  *domain,
		Port:                    *port,
		DefaultLat:              *defaultLat,
		DefaultLon:              *defaultLon,
		DefaultZoom:             *defaultZoom,
		DefaultLayer:            *defaultLayer,
		AutoLocateDefault:       *autoLocateDefault,
		SupportEmail:            *supportEmail,
		CompileVersion:          CompileVersion,
		DBType:                  *dbType,
		AdminPassword:           *adminPassword,
		APIDocsArchiveEnabled:   apiDocsArchiveEnabled,
		APIDocsArchiveRoute:     apiDocsArchiveRoute,
		APIDocsArchiveFrequency: apiDocsArchiveFrequency,
		DebugIPAllowlist:        debugIPAllowlist,
	}
	webServer := httpapi.NewWebServer(db, content, webConfig, log.Printf)

	// 4. Маршруты и статика
	staticFS, err := fs.Sub(content, "public_html")
	if err != nil {
		log.Fatalf("static fs: %v", err)
	}

	// Serve static files from embedded filesystem - this must come BEFORE the catch-all route
	// to avoid the map handler catching static file requests
	http.Handle("/static/", http.StripPrefix("/static/",
		http.FileServer(http.FS(staticFS))))

	// Serve JS files from the physical directory as a workaround
	// This ensures the marker-worker.js file is accessible to the browser
	// Access files from public_html root and let StripPrefix handle the path
	http.Handle("/js/", http.StripPrefix("/js/", http.FileServer(http.Dir("public_html/"))))

	http.HandleFunc("/home", homeHandler)
	http.HandleFunc("/", mapHandler)

	// Register authentication routes if auth system is enabled
	if authManager != nil {
		// Serve profile page
		http.HandleFunc("/profile", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			// Prevent CloudFront from caching user-specific pages
			w.Header().Set("Cache-Control", "no-cache, no-store, must-revalidate, private")
			w.Header().Set("Pragma", "no-cache")
			w.Header().Set("Expires", "0")

			lang := getPreferredLanguage(r)
			translationsMu.RLock()
			localTranslations := translations
			translationsMu.RUnlock()

			tmpl, err := template.New("profile.html").Funcs(template.FuncMap{
				"translate": func(key string) string {
					if val, ok := localTranslations[lang][key]; ok {
						return val
					}
					return localTranslations["en"][key]
				},
			}).ParseFS(content, "public_html/profile.html")
			if err != nil {
				http.Error(w, "Profile page not found", http.StatusNotFound)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			tmpl.Execute(w, nil)
		}))

		// Serve reset-password page
		http.HandleFunc("/reset-password", func(w http.ResponseWriter, r *http.Request) {
			data, err := content.ReadFile("public_html/reset-password.html")
			if err != nil {
				http.Error(w, "Reset password page not found", http.StatusNotFound)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			w.Write(data)
		})
	}

	// User admin routes (supports both URL password and session-based admin auth)
	if authManager != nil {
		// Helper function to check admin access (session-based or password-based)
		checkAdminAccess := func(w http.ResponseWriter, r *http.Request) bool {
			// First check for session-based admin auth
			if user, ok := auth.GetUserFromContext(r.Context()); ok && user.IsAdmin {
				return true
			}
			// Fall back to URL password
			if *adminPassword != "" {
				password := r.URL.Query().Get("password")
				if password == *adminPassword {
					return true
				}
			}
			http.Error(w, "Unauthorized - Please login as admin or provide password", http.StatusUnauthorized)
			return false
		}

		// Serve admin users page
		http.HandleFunc("/admin/users", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			// Prevent CloudFront from caching this dynamic admin page
			w.Header().Set("Cache-Control", "no-cache, no-store, must-revalidate, private")
			w.Header().Set("Pragma", "no-cache")
			w.Header().Set("Expires", "0")

			if !checkAdminAccess(w, r) {
				return
			}
			data, err := content.ReadFile("public_html/admin-users.html")
			if err != nil {
				http.Error(w, "Admin page not found", http.StatusNotFound)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			w.Write(data)
		}))

		// Serve admin uploads page (wrapper for /api/admin/uploads)
		http.HandleFunc("/admin/uploads", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			// Forward to the API endpoint which handles the uploads listing
			adminUploadsHandler(w, r)
		}))

		// Serve admin MCP analytics page
		http.HandleFunc("/admin/mcp", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Cache-Control", "no-cache, no-store, must-revalidate, private")
			w.Header().Set("Pragma", "no-cache")
			w.Header().Set("Expires", "0")

			if !checkAdminAccess(w, r) {
				return
			}
			data, err := content.ReadFile("public_html/admin-mcp.html")
			if err != nil {
				http.Error(w, "Admin MCP page not found", http.StatusNotFound)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			w.Write(data)
		}))

		// MCP analytics API endpoints
		http.HandleFunc("/api/admin/mcp/data", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			adminMCPDataHandler(w, r)
		}))
		http.HandleFunc("/api/admin/mcp/export", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			adminMCPExportHandler(w, r)
		}))
		http.HandleFunc("/api/admin/mcp/delete", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			adminMCPDeleteHandler(w, r)
		}))

		// Serve admin Realtime page and API endpoints
		http.HandleFunc("/admin/realtime", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Cache-Control", "no-cache, no-store, must-revalidate, private")
			w.Header().Set("Pragma", "no-cache")
			w.Header().Set("Expires", "0")

			if !checkAdminAccess(w, r) {
				return
			}
			data, err := content.ReadFile("public_html/admin-realtime.html")
			if err != nil {
				http.Error(w, "Admin Realtime page not found", http.StatusNotFound)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			w.Write(data)
		}))

		http.HandleFunc("/api/admin/realtime/data", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			adminRealtimeDataHandler(w, r)
		}))
		http.HandleFunc("/api/admin/realtime/export", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			adminRealtimeExportHandler(w, r)
		}))
		http.HandleFunc("/api/admin/realtime/delete", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			adminRealtimeDeleteHandler(w, r)
		}))

		// Admin translations page and API
		http.HandleFunc("/admin/translations", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			data, err := content.ReadFile("public_html/admin-translations.html")
			if err != nil {
				http.Error(w, "Page not found", http.StatusNotFound)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			w.Write(data)
		}))
		http.HandleFunc("/api/admin/translations/reload", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			adminTranslationsReloadHandler(w, r)
		}))
		http.HandleFunc("/api/admin/translations/", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			switch r.Method {
			case http.MethodPut:
				adminTranslationUpdateHandler(w, r)
			case http.MethodDelete:
				adminTranslationDeleteHandler(w, r)
			default:
				http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			}
		}))
		http.HandleFunc("/api/admin/translations", authManager.OptionalAuth(func(w http.ResponseWriter, r *http.Request) {
			if !checkAdminAccess(w, r) {
				return
			}
			switch r.Method {
			case http.MethodGet:
				adminTranslationsDataHandler(w, r)
			case http.MethodPost:
				adminTranslationCreateHandler(w, r)
			default:
				http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			}
		}))

	}

	// Upload endpoint - protected with auth if required
	if *requireAuth && authManager != nil {
		http.HandleFunc("/upload", authManager.RequireAuth(uploadHandler))
	} else {
		http.HandleFunc("/upload", uploadHandler)
	}
	http.HandleFunc("/upload/progress", progressHandler)
	http.HandleFunc("/get_markers", getMarkersHandler)
	// Note: /stream_markers is Server-Sent Events (streaming) so gzip is skipped.
	// Gzip doesn't work well with streaming responses due to buffering.
	http.HandleFunc("/stream_markers", streamMarkersHandler)
	http.HandleFunc("/realtime_history", realtimeHistoryHandler)
	http.HandleFunc("/trackid/", trackHandler)
	http.HandleFunc("/tracks/", tracksHandler)
	// api/docs, licenses/, api/geoip, s/, api/spectrum/, api/markers/spectra, api/tracks/bounds, api/track-info/, api/update-coordinates, qrpng — registered via webServer.Register above
	// API endpoints ship JSON/archives. Keeping registration close to other
	// routes avoids surprises for operators scanning main() for handlers.
	limiter := httpapi.NewRateLimiter(time.Minute)
	apiHandler := httpapi.NewHandler(db, *dbType, archiveGen, limiter, log.Printf, archiveFrequency)
	httpapi.Register(http.DefaultServeMux, httpapi.RegisterConfig{
		WebServer:                        webServer,
		APIHandler:                       apiHandler,
		AuthManager:                      authManager,
		DB:                               db,
		AdminPassword:                    *adminPassword,
		Logf:                             log.Printf,
		AdminUploadsHandler:              adminUploadsHandler,
		AdminTracksHandler:               adminTracksHandler,
		AdminBackfillHandler:             adminBackfillHandler,
		AdminBackfillCountriesHandler:    adminBackfillCountriesHandler,
		AdminDeleteTrackHandler:          adminDeleteTrackHandler,
		AdminDeleteMultipleTracksHandler: adminDeleteMultipleTracksHandler,
		AdminImportFromSafecastHandler:   adminImportFromSafecastHandler,
		AdminCacheHandler:                adminCacheHandler,
	})

	// Register MCP Server (AI assistant, REST API, Swagger) on port 3333
	// Uses existing PostgreSQL (db) and DuckDB (duckDB) connections
	RegisterMCP()

	// Selfupgrade runs in the background only when explicitly enabled so existing
	// installations keep their manual release cadence. We assemble the config
	// near main() so filesystem paths, database settings, and HTTP handlers stay
	// consistent with the rest of the binary.
	selfUpgradeCancel := startSelfUpgrade(context.Background(), dbCfg)
	if selfUpgradeCancel != nil {
		defer selfUpgradeCancel()
	}

	var rootHandler http.Handler = http.DefaultServeMux
	if shield := importShield(importDone, driverName, log.Printf); shield != nil {
		// Keep HTTP responsive while a single-user DB import runs by declining
		// DB-backed endpoints. The middleware only activates for file engines
		// so multi-user databases remain fully live during imports.
		rootHandler = shield(rootHandler)
	}
	rootHandler = withServerHeader(rootHandler)

	// 5. HTTP/HTTPS-серверы
	if *domain != "" {
		// Двойной сервер :80 + :443 с Let’s Encrypt
		go serveWithDomain(*domain, rootHandler)
	} else {
		// Обычный HTTP на порт из -port
		addr := fmt.Sprintf(":%d", *port)
		go func() {
			log.Printf("HTTP server ➜ http://localhost:%d", *port)
			if err := http.ListenAndServe(addr, rootHandler); err != nil {
				selfupgradeHandleServerError(err, log.Printf)
			}
		}()
	}

	// асинхронные индексы в бд без блокирования основного процесса начало
	ctxIdx, cancelIdx := context.WithCancel(context.Background())
	defer cancelIdx()
	// Пояснение в лог: что делаем и почему это не блокирует сервер
	log.Printf("⏳ background index build scheduled (engine=%s). Listeners are up; pages may be slower until indexes are ready.", dbCfg.DBType)
	// Запуск асинхронной индексации с прогрессом
	db.EnsureIndexesAsync(ctxIdx, dbCfg, func(format string, args ...any) {
		log.Printf(format, args...)
	})
	// асинхронные индексы в бд без блокирования основного процесса конец

	// 6. Держим main-goroutine живой
	select {}
}

