325→  <script>
326→    const urlParams = new URLSearchParams(window.location.search);
327→    const adminPassword = urlParams.get('password');
328→    let isAuthenticated = false;
329→
330→    // Pagination state
331→    let currentPage = 1;
332→    let pageSize = 50;
333→    let totalUsers = 0;
334→    let currentSearch = '';
335→    let allUsers = []; // Users on current page
336→
337→    // Helper function to add password parameter if needed
338→    function addPasswordParam(url) {
339→      if (adminPassword) {
340→        const separator = url.includes('?') ? '&' : '?';
341→        return url + separator + 'password=' + encodeURIComponent(adminPassword);
342→      }
343→      return url;
344→    }
