346→    // Check authentication on page load
347→    function buildAdminTabs() {
348→      const pw = new URLSearchParams(window.location.search).get('password') || '';
349→      const tabs = [
350→        { label: 'Users', href: '/admin/users', active: true },
351→        { label: 'Uploads', href: '/admin/uploads' },
352→        { label: 'MCP Analytics', href: '/admin/mcp' },
353→        { label: 'Realtime', href: '/admin/realtime' },
354→        { label: 'Translations', href: '/admin/translations' }
355→      ];
356→      const container = document.getElementById('adminTabs');
357→      tabs.forEach(t => {
358→        if (t.disabled) {
359→          container.innerHTML += '<span class="disabled">' + t.label + '</span>';
360→        } else {
361→          const href = t.href + (pw ? '?password=' + encodeURIComponent(pw) : '');
362→          container.innerHTML += '<a href="' + href + '" class="' + (t.active ? 'active' : '') + '">' + t.label + '</a>';
363→        }
364→      });
365→    }
366→
367→    let columnWidths = {};
368→    let resizing = false;
369→
370→    function initColumnResize() {
371→      const table = document.getElementById('usersTable');
372→      if (!table) return;
373→      const headerRow = table.querySelector('thead tr:first-child');
374→      if (!headerRow) return;
375→      const ths = headerRow.querySelectorAll('th');
376→
377→      ths.forEach((th, i) => {
378→        if (columnWidths[i]) {
379→          th.style.width = columnWidths[i];
380→        } else {
381→          th.style.width = th.offsetWidth + 'px';
382→        }
383→      });
384→
385→      document.querySelectorAll('.resize-handle').forEach(handle => {
386→        handle.addEventListener('mousedown', function(e) {
387→          e.preventDefault();
388→          e.stopPropagation();
389→          resizing = true;
390→          const th = this.parentElement;
391→          const colIndex = Array.from(th.parentElement.children).indexOf(th);
392→          const startX = e.pageX;
393→          const startWidth = th.offsetWidth;
394→          this.classList.add('active');
395→
396→          const onMouseMove = (e) => {
397→            const newWidth = Math.max(40, startWidth + (e.pageX - startX));
398→            th.style.width = newWidth + 'px';
399→            columnWidths[colIndex] = newWidth + 'px';
400→          };
401→          const onMouseUp = () => {
402→            this.classList.remove('active');
403→            document.removeEventListener('mousemove', onMouseMove);
404→            document.removeEventListener('mouseup', onMouseUp);
405→            setTimeout(() => { resizing = false; }, 50);
406→          };
407→          document.addEventListener('mousemove', onMouseMove);
408→          document.addEventListener('mouseup', onMouseUp);
409→        });
410→      });
411→    }
412→
413→    window.addEventListener('DOMContentLoaded', async function() {
414→      buildAdminTabs();
415→      initColumnResize();
416→      // Check if user is authenticated via session
417→      try {
418→        const response = await fetch('/api/user/profile');
419→        if (response.ok) {
420→          const user = await response.json();
421→          if (user.is_admin) {
422→            isAuthenticated = true;
423→          }
424→        }
425→      } catch (e) {
426→        // Session auth failed, check if password provided
427→      }
428→
429→      // If not authenticated via session and no password, redirect
430→      if (!isAuthenticated && !adminPassword) {
431→        alert('Access denied. Admin privileges required.');
432→        window.location.href = '/';
433→        return;
434→      }
435→
436→      syncPageSizeSelects();
437→      loadUsers();
438→    });
