440→    async function loadUsers() {
441→      const loadingIndicator = document.getElementById('loadingIndicator');
442→      const emptyState = document.getElementById('emptyState');
443→      const usersTable = document.getElementById('usersTable');
444→      const pagination = document.getElementById('pagination');
445→
446→      loadingIndicator.style.display = 'block';
447→      emptyState.style.display = 'none';
448→      usersTable.style.display = 'none';
449→      pagination.style.display = 'none';
450→
451→      const offset = (currentPage - 1) * pageSize;
452→
453→      try {
454→        let url = `/api/admin/users?limit=${pageSize}&offset=${offset}`;
455→        if (adminPassword) {
456→          url += `&password=${encodeURIComponent(adminPassword)}`;
457→        }
458→        if (currentSearch) {
459→          url += `&search=${encodeURIComponent(currentSearch)}`;
460→        }
461→
462→        const response = await fetch(url);
463→        if (!response.ok) {
464→          if (response.status === 403) {
465→            alert('Access denied. Admin privileges required.');
466→            window.location.href = '/';
467→            return;
468→          }
469→          throw new Error('Failed to load users');
470→        }
471→
472→        const data = await response.json();
473→        allUsers = data.users || [];
474→        totalUsers = data.total || 0;
475→
476→        loadingIndicator.style.display = 'none';
477→
478→        if (totalUsers === 0) {
479→          emptyState.style.display = 'block';
480→          document.getElementById('paginationTop').style.display = 'none';
481→        } else {
482→          usersTable.style.display = 'table';
483→          pagination.style.display = 'flex';
484→          document.getElementById('paginationTop').style.display = 'flex';
485→          renderUsers(allUsers);
486→          updateStats();
487→          renderPagination();
488→        }
489→      } catch (error) {
490→        loadingIndicator.style.display = 'none';
491→        alert('Error loading users: ' + error.message);
492→      }
493→    }
