495→    function renderUsers(users) {
496→      const tbody = document.getElementById('usersTableBody');
497→      tbody.innerHTML = '';
498→
499→      users.forEach(user => {
500→        const tr = document.createElement('tr');
501→        const adminBadge = user.is_admin
502→          ? '<span class="badge badge-admin">Admin</span>'
503→          : '<span class="badge badge-user">User</span>';
504→        const adminButton = user.is_admin
505→          ? `<button class="btn-remove-admin" onclick="toggleAdmin(${user.id}, false)">Remove Admin</button>`
506→          : `<button class="btn-admin" onclick="toggleAdmin(${user.id}, true)">Make Admin</button>`;
507→        tr.innerHTML = `
508→          <td class="checkbox-col"><input type="checkbox" class="user-checkbox" value="${user.id}" onchange="updateDeleteButton()"></td>
509→          <td>${user.id}</td>
