489→    async function deleteSelectedUsers() {
490→      const selected = Array.from(document.querySelectorAll('.select-user:checked'));
491→      if (selected.length === 0) return;
492→      if (!confirm(`Delete ${selected.length} selected user(s)? This cannot be undone.`)) return;
493→      const ids = selected.map(cb => cb.getAttribute('data-user-id'));
494→      let errors = [];
495→      for (const id of ids) {
496→        try {
497→          const response = await fetch(`/api/admin/users/${id}?password=${encodeURIComponent(adminPassword)}`, {
498→            method: 'DELETE'
499→          });
500→          if (!response.ok) {
501→            const error = await response.json();
502→            errors.push(error.error || `Failed to delete user ${id}`);
503→          }
504→        } catch (err) {
505→          errors.push(`Network error for user ${id}`);
506→        }
507→      }
508→      if (errors.length > 0) {
509→        alert('Some errors occurred:\n' + errors.join('\n'));
510→      }
511→      loadUsers();
