590→  <script>
591→    let allUsers = [];
592→    let editingUserId = null;
593→    let deletingUserId = null;
594→
595→    // Get password from URL
596→    const urlParams = new URLSearchParams(window.location.search);
597→    const adminPassword = urlParams.get('password');
598→
599→    if (!adminPassword) {
600→      alert('Missing password parameter');
601→      window.location.href = '/';
602→    }
603→
604→    // Load users on page load
605→    window.addEventListener('load', loadUsers);
606→
607→    // Search functionality
608→    document.getElementById('searchBox').addEventListener('input', function(e) {
609→      const searchTerm = e.target.value.toLowerCase();
610→      filterUsers(searchTerm);
611→    });
