613→    async function loadUsers() {
614→      const loadingIndicator = document.getElementById('loadingIndicator');
615→      const emptyState = document.getElementById('emptyState');
616→      const usersTable = document.getElementById('usersTable');
617→
618→      loadingIndicator.style.display = 'block';
619→      emptyState.style.display = 'none';
620→      usersTable.style.display = 'none';
621→
622→      try {
623→        const response = await fetch(`/api/admin/users?password=${encodeURIComponent(adminPassword)}`);
624→        if (!response.ok) {
625→          if (response.status === 403) {
626→            alert('Access denied. Admin privileges required.');
627→            window.location.href = '/';
628→            return;
629→          }
630→          throw new Error('Failed to load users');
631→        }
632→
633→        const data = await response.json();
634→        allUsers = data.users || [];
635→
636→        loadingIndicator.style.display = 'none';
637→
638→        if (allUsers.length === 0) {
639→          emptyState.style.display = 'block';
640→        } else {
641→          usersTable.style.display = 'table';
642→          renderUsers(allUsers);
643→          updateStats();
644→        }
645→      } catch (error) {
646→        loadingIndicator.style.display = 'none';
647→        alert('Error loading users: ' + error.message);
648→      }
649→    }
650→
651→    function renderUsers(users) {
652→      const tbody = document.getElementById('usersTableBody');
653→      tbody.innerHTML = '';
654→
655→      users.forEach(user => {
656→        const tr = document.createElement('tr');
657→        tr.innerHTML = `
658→          <td><input type="checkbox" class="select-user" data-user-id="${user.id}"></td>
659→          <td>${user.id}</td>
660→          <td>${user.email}</td>
661→          <td class="username-cell" title="${user.username || ''}">${user.username ? user.username : '<em>none</em>'}</td>
662→          <td><span class="badge ${user.is_active ? 'badge-active' : 'badge-inactive'}">${user.is_active ? 'Active' : 'Inactive'}</span></td>
663→          <td><span class="badge ${user.email_verified ? 'badge-verified' : 'badge-unverified'}">${user.email_verified ? 'Verified' : 'Unverified'}</span></td>
664→          <td>${formatDate(user.created_at)}</td>
665→          <td>${user.last_login_at ? formatDate(user.last_login_at) : 'Never'}</td>
666→          <td class="action-buttons">
667→            <button class="icon-btn btn-primary" onclick="editUser(${user.id})">Edit</button>
668→            <button class="icon-btn btn-warning" onclick="resetUserPassword(${user.id})">Reset Password</button>
669→            <button class="icon-btn btn-danger" onclick="deleteUser(${user.id})">Delete</button>
670→          </td>
671→        `;
672→        tbody.appendChild(tr);
673→      });
674→    }
675→
676→    // Multi-select logic - only selects currently visible (filtered) users
677→    function toggleSelectAllUsers(checkbox) {
678→      const checkboxes = document.querySelectorAll('.select-user');
679→      checkboxes.forEach(cb => { cb.checked = checkbox.checked; });
680→      updateDeleteSelectedBtn();
681→    }
682→
683→    // Sorting functionality
684→    let sortDirection = {};
685→    function sortTable(columnIndex) {
686→      const table = document.getElementById('usersTable');
687→      const tbody = document.getElementById('usersTableBody');
688→      const rows = Array.from(tbody.querySelectorAll('tr'));
689→      const header = table.querySelector('thead tr th:nth-child(' + (columnIndex + 1) + ')');
690→      const dataType = header.getAttribute('data-type');
691→
692→      // Toggle sort direction
693→      const currentDir = sortDirection[columnIndex] || 'none';
694→      sortDirection[columnIndex] = currentDir === 'asc' ? 'desc' : 'asc';
695→
696→      // Remove sort classes from all headers
697→      table.querySelectorAll('.sortable').forEach(h => {
698→        h.classList.remove('asc', 'desc');
699→      });
700→
701→      // Add sort class to current header
702→      header.classList.add(sortDirection[columnIndex]);
703→
704→      // Sort rows
705→      rows.sort((a, b) => {
706→        let aVal = a.cells[columnIndex].textContent.trim();
707→        let bVal = b.cells[columnIndex].textContent.trim();
708→
709→        // Numeric comparison
710→        if (dataType === 'number') {
711→          aVal = parseInt(aVal) || 0;
712→          bVal = parseInt(bVal) || 0;
713→          return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
714→        }
715→
716→        // Date comparison
717→        if (dataType === 'date') {
718→          // Handle "Never" text for last login
719→          if (aVal === 'Never') aVal = new Date(0).toISOString();
720→          if (bVal === 'Never') bVal = new Date(0).toISOString();
721→          aVal = new Date(aVal).getTime();
722→          bVal = new Date(bVal).getTime();
723→          return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
724→        }
725→
726→        // Text comparison (handles badges like Active/Inactive, Verified/Unverified)
727→        if (sortDirection[columnIndex] === 'asc') {
728→          return aVal.localeCompare(bVal);
729→        } else {
730→          return bVal.localeCompare(aVal);
731→        }
732→      });
733→
734→      // Reappend sorted rows
735→      rows.forEach(row => tbody.appendChild(row));
736→    }
737→
738→    function filterUsers(searchTerm) {
739→      if (!searchTerm) {
740→        renderUsers(allUsers);
741→        return;
742→      }
743→
744→      const filtered = allUsers.filter(user =>
745→        user.email.toLowerCase().includes(searchTerm) ||
746→        (user.username && user.username.toLowerCase().includes(searchTerm))
747→      );
748→
749→      renderUsers(filtered);
750→    }
751→
752→    function updateStats() {
753→      document.getElementById('totalUsers').textContent = allUsers.length;
754→      document.getElementById('activeUsers').textContent = allUsers.filter(u => u.is_active).length;
755→      document.getElementById('verifiedUsers').textContent = allUsers.filter(u => u.email_verified).length;
756→    }
