764→    function showAddUserModal() {
765→      editingUserId = null;
766→      document.getElementById('modalTitle').textContent = 'Add User';
767→      document.getElementById('userForm').reset();
768→      document.getElementById('userId').value = '';
769→      document.getElementById('userIsActive').checked = true;
770→      document.getElementById('userEmailVerified').checked = false;
771→      document.getElementById('userSendSetupEmail').checked = true;
772→      document.getElementById('passwordGroup').style.display = 'block';
773→      document.getElementById('setupEmailGroup').style.display = 'block';
774→      document.getElementById('modalMessage').style.display = 'none';
775→      document.getElementById('userModal').classList.add('active');
776→    }
