778→    function editUser(userId) {
779→      const user = allUsers.find(u => u.id === userId);
780→      if (!user) return;
781→
782→      editingUserId = userId;
783→      document.getElementById('modalTitle').textContent = 'Edit User';
784→      document.getElementById('userId').value = user.id;
785→      document.getElementById('userEmail').value = user.email;
786→      document.getElementById('userUsername').value = user.username || '';
787→      document.getElementById('userIsActive').checked = user.is_active;
788→      document.getElementById('userEmailVerified').checked = user.email_verified;
789→      document.getElementById('passwordGroup').style.display = 'none';
790→      document.getElementById('setupEmailGroup').style.display = 'none';
791→      document.getElementById('modalMessage').style.display = 'none';
792→      document.getElementById('userModal').classList.add('active');
793→    }
