799→    async function saveUser(event) {
800→      event.preventDefault();
801→
802→      const userId = document.getElementById('userId').value;
803→      const email = document.getElementById('userEmail').value;
804→      const username = document.getElementById('userUsername').value;
805→      const password = document.getElementById('userPassword').value;
806→      const isActive = document.getElementById('userIsActive').checked;
807→      const emailVerified = document.getElementById('userEmailVerified').checked;
808→      const sendSetupEmail = document.getElementById('userSendSetupEmail').checked;
809→
810→      const modalMessage = document.getElementById('modalMessage');
811→
812→      try {
813→        let response;
814→        if (userId) {
815→          // Update existing user
816→          response = await fetch(`/api/admin/users/${userId}?password=${encodeURIComponent(adminPassword)}`, {
817→            method: 'PUT',
818→            headers: { 'Content-Type': 'application/json' },
819→            body: JSON.stringify({
820→              email,
821→              username: username || null,
822→              is_active: isActive,
823→              email_verified: emailVerified
824→            })
825→          });
826→        } else {
827→          // Create new user
828→          response = await fetch(`/api/admin/users/create?password=${encodeURIComponent(adminPassword)}`, {
829→            method: 'POST',
830→            headers: { 'Content-Type': 'application/json' },
831→            body: JSON.stringify({
832→              email,
833→              username: username || null,
834→              password: password || null,
835→              send_welcome_email: !sendSetupEmail,
836→              requires_password_setup: sendSetupEmail || !password
837→            })
838→          });
839→        }
840→
841→        if (response.ok) {
842→          modalMessage.textContent = userId ? 'User updated successfully!' : 'User created successfully!';
843→          modalMessage.className = 'message success';
844→          modalMessage.style.display = 'block';
845→
846→          setTimeout(() => {
847→            closeUserModal();
848→            loadUsers();
849→          }, 1500);
850→        } else {
851→          const error = await response.json();
852→          modalMessage.textContent = error.error || 'Failed to save user';
853→          modalMessage.className = 'message error';
854→          modalMessage.style.display = 'block';
855→        }
856→      } catch (error) {
857→        modalMessage.textContent = 'Network error: ' + error.message;
858→        modalMessage.className = 'message error';
859→        modalMessage.style.display = 'block';
860→      }
861→    }
862→
863→    async function resetUserPassword(userId) {
864→      if (!confirm('Send a password reset email to this user?')) return;
865→
866→      try {
867→        const response = await fetch(`/api/admin/users/${userId}/reset-password?password=${encodeURIComponent(adminPassword)}`, {
868→          method: 'POST'
869→        });
870→
871→        if (response.ok) {
872→          alert('Password reset email sent successfully!');
873→        } else {
874→          const error = await response.json();
875→          alert('Error: ' + (error.error || 'Failed to send password reset email'));
876→        }
877→      } catch (error) {
878→        alert('Network error: ' + error.message);
879→      }
880→    }
881→
882→    function deleteUser(userId) {
883→      const user = allUsers.find(u => u.id === userId);
884→      if (!user) return;
885→
886→      deletingUserId = userId;
887→      document.getElementById('deleteUserEmail').textContent = user.email;
888→      document.getElementById('deleteModal').classList.add('active');
889→    }
890→
891→    function closeDeleteModal() {
892→      document.getElementById('deleteModal').classList.remove('active');
893→      deletingUserId = null;
894→    }
895→
896→    async function confirmDelete() {
897→      if (!deletingUserId) return;
898→
899→      try {
900→        const response = await fetch(`/api/admin/users/${deletingUserId}?password=${encodeURIComponent(adminPassword)}`, {
901→          method: 'DELETE'
902→        });
903→
904→        if (response.ok) {
905→          closeDeleteModal();
906→          loadUsers();
907→        } else {
908→          const error = await response.json();
909→          alert('Error: ' + (error.error || 'Failed to delete user'));
910→        }
911→      } catch (error) {
912→        alert('Network error: ' + error.message);
913→      }
914→    }
915→  </script>
916→</body>
