311→  <script>
312→    const urlParams = new URLSearchParams(window.location.search);
313→    const adminPassword = urlParams.get('password');
314→    let isAuthenticated = false;
315→
316→    // Pagination state
317→    let currentPage = 1;
318→    let pageSize = 50;
319→    let totalUsers = 0;
320→    let currentSearch = '';
