322→
323→    // Helper function to add password parameter if needed
324→    function addPasswordParam(url) {
325→      if (adminPassword) {
326→        const separator = url.includes('?') ? '&' : '?';
327→        return url + separator + 'password=' + encodeURIComponent(adminPassword);
328→      }
329→      return url;
