332→    // Check authentication on page load
333→    window.addEventListener('DOMContentLoaded', async function() {
334→      // Check if user is authenticated via session
335→      try {
336→        const response = await fetch('/api/user/profile');
337→        if (response.ok) {
338→          const user = await response.json();
339→          if (user.is_admin) {
340→            isAuthenticated = true;
341→          }
342→        }
343→      } catch (e) {
344→        // Session auth failed, check if password provided
345→      }
346→
347→      // If not authenticated via session and no password, redirect
348→      if (!isAuthenticated && !adminPassword) {
349→        alert('Access denied. Admin privileges required.');
350→        window.location.href = '/';
351→        return;
