358→    async function loadUsers() {
359→      const loadingIndicator = document.getElementById('loadingIndicator');
360→      const emptyState = document.getElementById('emptyState');
361→      const usersTable = document.getElementById('usersTable');
362→      const pagination = document.getElementById('pagination');
363→
364→      loadingIndicator.style.display = 'block';
365→      emptyState.style.display = 'none';
366→      usersTable.style.display = 'none';
367→      pagination.style.display = 'none';
368→
369→      const offset = (currentPage - 1) * pageSize;
370→
371→      try {
372→        let url = `/api/admin/users?limit=${pageSize}&offset=${offset}`;
373→        if (adminPassword) {
374→          url += `&password=${encodeURIComponent(adminPassword)}`;
375→        }
376→        if (currentSearch) {
377→          url += `&search=${encodeURIComponent(currentSearch)}`;
378→        }
379→
380→        const response = await fetch(url);
381→        if (!response.ok) {
382→          if (response.status === 403) {
383→            alert('Access denied. Admin privileges required.');
384→            window.location.href = '/';
385→            return;
386→          }
387→          throw new Error('Failed to load users');
388→        }
389→
390→        const data = await response.json();
391→        allUsers = data.users || [];
392→        totalUsers = data.total || 0;
393→
394→        loadingIndicator.style.display = 'none';
395→
396→        if (totalUsers === 0) {
397→          emptyState.style.display = 'block';
398→          document.getElementById('paginationTop').style.display = 'none';
399→        } else {
400→          usersTable.style.display = 'table';
401→          pagination.style.display = 'flex';
402→          document.getElementById('paginationTop').style.display = 'flex';
403→          renderUsers(allUsers);
404→          updateStats();
405→          renderPagination();
406→        }
407→      } catch (error) {
408→        loadingIndicator.style.display = 'none';
409→        alert('Error loading users: ' + error.message);
410→      }
411→    }
