413→    function renderUsers(users) {
414→      const tbody = document.getElementById('usersTableBody');
415→      tbody.innerHTML = '';
416→
417→      users.forEach(user => {
418→        const tr = document.createElement('tr');
419→        const adminBadge = user.is_admin
420→          ? '<span class="badge badge-admin">Admin</span>'
421→          : '<span class="badge badge-user">User</span>';
422→        const adminButton = user.is_admin
423→          ? `<button class="btn-remove-admin" onclick="toggleAdmin(${user.id}, false)">Remove Admin</button>`
424→          : `<button class="btn-admin" onclick="toggleAdmin(${user.id}, true)">Make Admin</button>`;
425→        tr.innerHTML = `
426→          <td class="checkbox-col"><input type="checkbox" class="user-checkbox" value="${user.id}" onchange="updateDeleteButton()"></td>
427→          <td>${user.id}</td>
428→          <td>${user.email}</td>
429→          <td class="username-cell" title="${user.username || ''}">${user.username || '<em>none</em>'}</td>
430→          <td>${user.external_id || '<em>none</em>'}</td>
431→          <td class="api-key-cell" title="${user.api_key || ''}">${user.api_key || '<em>none</em>'}</td>
432→          <td><span class="badge ${user.is_active ? 'badge-active' : 'badge-inactive'}">${user.is_active ? 'Active' : 'Inactive'}</span></td>
433→          <td>${adminBadge}</td>
434→          <td><span class="badge ${user.email_verified ? 'badge-verified' : 'badge-unverified'}">${user.email_verified ? 'Verified' : 'Unverified'}</span></td>
435→          <td>${formatDate(user.created_at)}</td>
436→          <td>${user.last_login_at ? formatDate(user.last_login_at) : 'Never'}</td>
437→          <td class="actions-cell">
438→            ${adminButton}
439→            <button class="btn-edit" onclick="editUser(${user.id})">Edit</button>
440→            <button class="btn-warning" onclick="resetUserPassword(${user.id})">Reset Password</button>
441→            <button class="delete-btn" onclick="deleteUser(${user.id})">Delete</button>
442→          </td>
443→        `;
444→        tbody.appendChild(tr);
445→      });
446→
447→      // Reset select all checkbox
448→      document.getElementById('selectAll').checked = false;
449→      updateDeleteButton();
