457→    function renderPagination() {
458→      const totalPages = Math.ceil(totalUsers / pageSize);
459→
460→      // Render to both top and bottom pagination controls
461→      renderPaginationControls(document.getElementById('paginationControls'), totalPages);
462→      renderPaginationControls(document.getElementById('paginationTop'), totalPages);
463→    }
464→
465→    function renderPaginationControls(controls, totalPages) {
466→      controls.innerHTML = '';
467→
468→      // First/Previous buttons
469→      const firstBtn = document.createElement('button');
470→      firstBtn.className = 'pagination-btn';
471→      firstBtn.textContent = 'First';
472→      firstBtn.disabled = currentPage === 1;
473→      firstBtn.onclick = () => goToPage(1);
474→      controls.appendChild(firstBtn);
475→
476→      const prevBtn = document.createElement('button');
477→      prevBtn.className = 'pagination-btn';
478→      prevBtn.textContent = 'Prev';
479→      prevBtn.disabled = currentPage === 1;
480→      prevBtn.onclick = () => goToPage(currentPage - 1);
481→      controls.appendChild(prevBtn);
482→
483→      // Page numbers
484→      const startPage = Math.max(1, currentPage - 2);
485→      const endPage = Math.min(totalPages, currentPage + 2);
486→
487→      if (startPage > 1) {
488→        const ellipsis = document.createElement('span');
489→        ellipsis.textContent = '...';
490→        ellipsis.style.padding = '0 5px';
491→        controls.appendChild(ellipsis);
492→      }
493→
494→      for (let i = startPage; i <= endPage; i++) {
495→        const pageBtn = document.createElement('button');
496→        pageBtn.className = 'pagination-btn' + (i === currentPage ? ' active' : '');
497→        pageBtn.textContent = i;
498→        pageBtn.onclick = () => goToPage(i);
499→        controls.appendChild(pageBtn);
500→      }
501→
502→      if (endPage < totalPages) {
503→        const ellipsis = document.createElement('span');
504→        ellipsis.textContent = '...';
505→        ellipsis.style.padding = '0 5px';
506→        controls.appendChild(ellipsis);
507→      }
508→
509→      // Next/Last buttons
510→      const nextBtn = document.createElement('button');
511→      nextBtn.className = 'pagination-btn';
512→      nextBtn.textContent = 'Next';
513→      nextBtn.disabled = currentPage === totalPages || totalPages === 0;
514→      nextBtn.onclick = () => goToPage(currentPage + 1);
515→      controls.appendChild(nextBtn);
516→
517→      const lastBtn = document.createElement('button');
518→      lastBtn.className = 'pagination-btn';
519→      lastBtn.textContent = 'Last';
520→      lastBtn.disabled = currentPage === totalPages || totalPages === 0;
521→      lastBtn.onclick = () => goToPage(totalPages);
522→      controls.appendChild(lastBtn);
523→
524→      // Page info
525→      const pageInfo = document.createElement('span');
526→      pageInfo.style.marginLeft = '15px';
527→      pageInfo.style.color = 'var(--text-secondary)';
528→      const startItem = (currentPage - 1) * pageSize + 1;
529→      const endItem = Math.min(currentPage * pageSize, totalUsers);
530→      pageInfo.textContent = `${startItem}-${endItem} of ${totalUsers}`;
531→      controls.appendChild(pageInfo);
532→    }
