558→    function formatDate(timestamp) {
559→      if (!timestamp) return 'N/A';
560→      const date = new Date(timestamp * 1000);
561→      return date.toISOString().split('T')[0];
562→    }
563→
564→    // Sorting functionality (client-side for current page)
565→    let sortDirection = {};
566→    function sortTable(columnIndex) {
567→      const table = document.getElementById('usersTable');
568→      const tbody = document.getElementById('usersTableBody');
569→      const rows = Array.from(tbody.querySelectorAll('tr'));
570→      const header = table.querySelector('thead tr:first-child th:nth-child(' + (columnIndex + 1) + ')');
571→      const dataType = header.getAttribute('data-type');
572→
573→      const currentDir = sortDirection[columnIndex] || 'none';
574→      sortDirection[columnIndex] = currentDir === 'asc' ? 'desc' : 'asc';
575→
576→      table.querySelectorAll('.sortable').forEach(h => h.classList.remove('asc', 'desc'));
577→      header.classList.add(sortDirection[columnIndex]);
578→
579→      rows.sort((a, b) => {
580→        let aVal = a.cells[columnIndex].textContent.trim();
581→        let bVal = b.cells[columnIndex].textContent.trim();
582→
583→        if (dataType === 'number') {
584→          aVal = parseInt(aVal) || 0;
585→          bVal = parseInt(bVal) || 0;
586→          return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
587→        }
588→
589→        if (dataType === 'date') {
590→          if (aVal === 'Never') aVal = new Date(0).toISOString();
591→          if (bVal === 'Never') bVal = new Date(0).toISOString();
592→          aVal = new Date(aVal).getTime();
593→          bVal = new Date(bVal).getTime();
594→          return sortDirection[columnIndex] === 'asc' ? aVal - bVal : bVal - aVal;
595→        }
596→
597→        if (sortDirection[columnIndex] === 'asc') {
598→          return aVal.localeCompare(bVal);
599→        } else {
600→          return bVal.localeCompare(aVal);
601→        }
602→      });
603→
604→      rows.forEach(row => tbody.appendChild(row));
605→    }
606→
607→    // Column filtering (client-side for current page)
608→    function filterTable() {
609→      const table = document.getElementById('usersTable');
610→      const tbody = document.getElementById('usersTableBody');
611→      const filters = table.querySelectorAll('.filter-input');
612→      const rows = tbody.querySelectorAll('tr');
613→
614→      rows.forEach(row => {
615→        let show = true;
616→        filters.forEach((filter, index) => {
617→          const filterValue = filter.value.toLowerCase();
618→          if (filterValue) {
619→            const cellIndex = index + 1;
620→            const cell = row.cells[cellIndex];
621→            if (cell) {
622→              const cellText = cell.textContent.toLowerCase();
623→              if (!cellText.includes(filterValue)) {
624→                show = false;
625→              }
626→            }
627→          }
628→        });
629→        row.style.display = show ? '' : 'none';
630→      });
631→    }
