667→    async function deleteSelectedUsers() {
668→      const selected = Array.from(document.querySelectorAll('.user-checkbox:checked'));
669→      if (selected.length === 0) return;
670→      if (!confirm(`Delete ${selected.length} selected user(s)? This cannot be undone.`)) return;
671→
672→      const ids = selected.map(cb => cb.value);
673→      let errors = [];
674→      for (const id of ids) {
675→        try {
676→          const response = await fetch(addPasswordParam(`/api/admin/users/${id}`), {
677→            method: 'DELETE'
678→          });
679→          if (!response.ok) {
680→            const error = await response.json();
681→            errors.push(error.error || `Failed to delete user ${id}`);
682→          }
683→        } catch (err) {
684→          errors.push(`Network error for user ${id}`);
685→        }
686→      }
687→      if (errors.length > 0) {
688→        alert('Some errors occurred:\n' + errors.join('\n'));
689→      }
690→      loadUsers();
691→    }
