749→    async function saveUser(event) {
750→      event.preventDefault();
751→
752→      const userId = document.getElementById('userId').value;
753→      const userData = {
754→        email: document.getElementById('userEmail').value,
755→        username: document.getElementById('userUsername').value || null,
756→        password: document.getElementById('userPassword').value || null,
757→        is_active: document.getElementById('userStatus').value === 'true',
758→        is_admin: document.getElementById('userIsAdmin').value === 'true',
759→        email_verified: document.getElementById('userEmailVerified').value === 'true',
760→        external_id: document.getElementById('userExternalId').value || null
761→      };
762→
763→      try {
764→        let response;
765→        if (userId) {
766→          // Edit user
767→          if (!userData.password) delete userData.password;
768→          response = await fetch(addPasswordParam(`/api/admin/users/${userId}`), {
769→            method: 'PUT',
770→            headers: { 'Content-Type': 'application/json' },
771→            body: JSON.stringify(userData)
772→          });
773→        } else {
774→          // Add user
775→          if (!userData.password) {
776→            alert('Password is required for new users');
777→            return;
778→          }
779→          response = await fetch(addPasswordParam(`/api/admin/users/create`), {
780→            method: 'POST',
781→            headers: { 'Content-Type': 'application/json' },
782→            body: JSON.stringify(userData)
783→          });
784→        }
785→
786→        if (!response.ok) {
787→          const error = await response.json();
788→          throw new Error(error.error || 'Failed to save user');
789→        }
790→
791→        closeUserModal();
792→        loadUsers();
793→      } catch (error) {
794→        const msgEl = document.getElementById('modalMessage');
795→        msgEl.textContent = error.message;
796→        msgEl.className = 'message error';
797→        msgEl.style.display = 'block';
798→      }
799→    }
